"""

from dataclasses import dataclass
from typing import Tuple, Dict, List
import math

CONSTS = {
    "leptons": {
        "electron_mass_GeV": 0.00051099895,
        "muon_mass_GeV":     0.1056583755,
        "tau_mass_GeV":      1.77686,
        "higgs_mass_GeV":    125.10,
    },
    "scales": {"m_star_GeV": 9.0346e17},
    "defaults": {"lambda": 0.1045}
}

@dataclass
class FitResult:
    value: float
    note: str = ""

def mass_from_theta(m_star: float, theta4: float) -> float:
    return m_star * (math.sin(theta4) ** 2)

def theta_from_mass(m_star: float, m: float) -> float:
    s2 = max(0.0, min(1.0, m / m_star))
    return math.asin(math.sqrt(s2))

def implied_sin2_theta(m_star: float, m: float) -> float:
    return max(0.0, min(1.0, m / m_star))

def lambda_from_mass_ratio(m1: float, m2: float, delta_K: int) -> FitResult:
    if delta_K == 0:
        return FitResult(float('nan'), note="ΔK=0 invalid")
    val = abs(math.log(m2/m1) / delta_K)
    return FitResult(val, note="abs(lambda) from two-point ratio")

def predict_ratio_from_lambda(delta_K: int, lam: float) -> float:
    return math.exp(-lam * delta_K)

def assign_K_three_masses(m_e: float, m_mu: float, m_tau: float, lam: float):
    dK_e_mu = round(abs(math.log(m_mu/m_e)/lam))
    dK_mu_tau = round(abs(math.log(m_tau/m_mu)/lam))
    K_mu = 0
    K_e = K_mu + dK_e_mu
    K_tau = K_mu - dK_mu_tau
    return K_e, K_mu, K_tau, dK_e_mu, dK_mu_tau

def overlap(delta_K: int, lam: float) -> float:
    return math.exp(-lam * abs(delta_K))

def gminus2_mu_estimate(lam: float, deltaK_mu_L4: int, m_mu_GeV: float, m_L4_GeV: float, m_H_GeV: float, prefactor: float = 1.0) -> FitResult:
    y = overlap(deltaK_mu_L4, lam)
    delta_a = prefactor * (y*y) * (m_mu_GeV * m_L4_GeV) / (8.0 * math.pi**2 * m_H_GeV**2)
    return FitResult(delta_a, note="Crude 1-loop scaling; model-dependent constants omitted")

def delta_beta_deg(g_theta_gamma: float, delta_theta4: float) -> float:
    return 0.5 * g_theta_gamma * delta_theta4 * 180.0/math.pi

def theta4_kink_profile(x: float, x0: float, width: float, delta: float = 2*math.pi/3) -> float:
    t = 0.5*(1.0 + math.tanh((x - x0)/max(1e-9, width)))
    return delta * t

def run_tests() -> Dict[str, Dict]:
    m_star = CONSTS["scales"]["m_star_GeV"]
    m = CONSTS["leptons"]
    m_e, m_mu, m_tau, m_H = m["electron_mass_GeV"], m["muon_mass_GeV"], m["tau_mass_GeV"], m["higgs_mass_GeV"]
    lam = CONSTS["defaults"]["lambda"]
    results = {}

    s2_e, s2_mu, s2_tau = implied_sin2_theta(m_star, m_e), implied_sin2_theta(m_star, m_mu), implied_sin2_theta(m_star, m_tau)
    th_e, th_mu, th_tau = theta_from_mass(m_star, m_e), theta_from_mass(m_star, m_mu), theta_from_mass(m_star, m_tau)
    ok_inv = all(0 < s2 < 1 for s2 in (s2_e, s2_mu, s2_tau)) and              all(abs(implied_sin2_theta(m_star, mass_from_theta(m_star, th)) - s2) < 1e-12
                 for s2, th in ((s2_e, th_e), (s2_mu, th_mu), (s2_tau, th_tau)))
    results["mass_tilt_inversion"] = {"pass": bool(ok_inv)}

    lam_e_mu = lambda_from_mass_ratio(m_e, m_mu, delta_K=51).value
    lam_mu_tau = lambda_from_mass_ratio(m_mu, m_tau, delta_K=27).value
    ok_lam = all(0.08 <= x <= 0.12 for x in (lam_e_mu, lam_mu_tau))
    results["ladder_lambda_range"] = {"pass": bool(ok_lam), "lam_e_mu": lam_e_mu, "lam_mu_tau": lam_mu_tau}

    dKs = [0,1,5,20,40]
    vals = [overlap(dK, lam) for dK in dKs]
    ok_mon = all(vals[i] >= vals[i+1] for i in range(len(vals)-1))
    results["overlap_monotone"] = {"pass": bool(ok_mon), "values": vals}

    est = gminus2_mu_estimate(lam, 39, m_mu, 105.0, m_H).value
    ok_g2 = (1.6e-9 <= est <= 3.4e-9)
    results["gminus2_window"] = {"pass": bool(ok_g2), "delta_a_mu": est}

    delta_theta4 = 2*math.pi/3
    gvals = [1e-4, 1e-3, 1e-2]
    db = [delta_beta_deg(g, delta_theta4) for g in gvals]
    ok_lin = abs((db[1]/db[0]) - 10.0) < 0.1 and abs((db[2]/db[1]) - 10.0) < 0.1
    results["birefringence_linear"] = {"pass": bool(ok_lin), "deg": db}
    return results

def tests_green(results: Dict[str, Dict]) -> bool:
    return all(v.get("pass", False) for v in results.values())

